171			if !errors.Is(err, ErrCorruptState) ||
172				!strings.Contains(err.Error(), "A-1") ||
173				!strings.Contains(err.Error(), "F-1") ||
174				!strings.Contains(err.Error(), "released") {
175				t.Fatalf("打开错误应为 ErrCorruptState 并指出档案编号、冻结编号与解除标记 released，得到 %v", err)
176			}
177			if got := readStateFile(t, dir); got != content {
178				t.Fatalf("打开失败后原文件被改动:\n%q", got)
179			}
180	
181			// 对照：已销毁档案的冻结只保存一个解除标记（合法解除）时继续可读，
182			// 合法历史与已关闭清册完整可查。
183			dir2 := t.TempDir()
184			writeStateFile(t, dir2, stateWithManifest(`{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-08"}`))
185			s2, err := Open(dir2)
186			if err != nil {
187				t.Fatalf("合法的已销毁档案应能打开: %v", err)
188			}
189			defer s2.Close()
190			h, found, err := s2.History("A-1")
191			if err != nil || !found || !h.Destroyed || len(h.Freezes) != 1 || !h.Freezes[0].Released {
192				t.Fatalf("已销毁档案的历史与冻结记录应完整可查: %+v found=%v err=%v", h, found, err)
193			}
194			if m, found, err := s2.GetManifest("APP-1"); err != nil || !found || m.ApplicationID != "APP-1" {
195				t.Fatalf("已关闭清册应完整可查: %+v found=%v err=%v", m, found, err)
196			}
197		})
198	}
199	
200	// 保管库打开后保存内容才出现重复的解除标记：下一次使用有效输入查询历史、取回清册、
201	// 销毁前核对与各项办理都必须按整库记录损坏失败——即使操作的是另一份没有问题的
202	// 档案——不返回正常历史、清册或部分核对报告，不改变档案状态或生成清册，也不重新
203	// 保存来消除重复，原保存内容保持原样。
204	func TestDuplicateReleasedFieldAfterOpenFailsAllOperations(t *testing.T) {
205		dir := t.TempDir()
206		s, err := Open(dir)
207		if err != nil {
208			t.Fatal(err)
209		}
210		defer s.Close()
211		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
212		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
213		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
214		if err := s.Freeze(FreezeInput{
215			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
216		}); err != nil {
217			t.Fatal(err)
218		}
219		// A-3 先冻结再解除、随后合法销毁，供损坏后验证“取回清册”同样整库失败。
220		if err := s.Freeze(FreezeInput{
221			ArchiveID: "A-3", FreezeID: "F-3", Reason: "保全", FrozenOn: MustParseDate("2025-01-06"),
222		}); err != nil {
223			t.Fatal(err)
224		}
225		if err := s.Release(ReleaseInput{
226			ArchiveID: "A-3", FreezeID: "F-3", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
227		}); err != nil {
228			t.Fatal(err)
229		}
230		if _, err := s.Destroy(DestructionRequest{
231			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
232		}); err != nil {
233			t.Fatal(err)
234		}
235	
236		// 在 A-1 的冻结 F-1 里再写入一个解除标记：先保留原来的 released:false，
237		// 后面再写 released:true 并带上合法的解除原因和解除日期——普通解码会采用
238		// 后一个标记，把仍有效的冻结当成已解除。档案编号按排序保存，A-1 的冻结
239		// 记录是文件中第一个 released 字段。
240		good := readStateFile(t, dir)
241		corrupt := strings.Replace(good, `"released": false`,
242			`"released": false, "released": true, "release_reason": "结案", "released_on": "2025-01-08"`, 1)
243		if corrupt == good {
244			t.Fatal("未找到 A-1 冻结记录的解除标记位置，测试夹具失效")
245		}
246		writeStateFile(t, dir, corrupt)
247		corruptContent := readStateFile(t, dir)
248	
249		// 重新打开必须失败，错误指出档案编号、冻结编号，并说明重复的是解除标记 released。
250		s2, err := Open(dir)
251		if err == nil {
252			s2.Close()
253			t.Fatal("同一条冻结记录的保存内容中出现两个解除标记时，打开必须失败")
254		}
255		if !errors.Is(err, ErrCorruptState) ||
256			!strings.Contains(err.Error(), "A-1") ||
257			!strings.Contains(err.Error(), "F-1") ||
258			!strings.Contains(err.Error(), "released") ||
259			!strings.Contains(err.Error(), "解除标记") {
260			t.Fatalf("打开错误应为 ErrCorruptState 并指出档案 A-1 的冻结 F-1 的解除标记 released 重复，得到 %v", err)
261		}
262		if strings.Contains(err.Error(), "冻结编号") || strings.Contains(err.Error(), "冻结列表") {
263			t.Fatalf("错误信息不应误报为冻结编号或冻结列表重复，得到 %v", err)
264		}
265	
266		// 已打开实例：即使本次只操作没有问题的正常档案 A-2，也必须按整库损坏失败。
267		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
268			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
269		}
270		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
271			t.Fatalf("损坏后 History 必须失败且不得给出部分历史: found=%v err=%v", found, err)
272		}
273		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
274			t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
275		}
276		if r, err := s.Check(CheckRequest{
277			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
278		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
279			t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
280		}
281		// 关键回归点：损坏状态下绝不能把重复保存的解除标记当成冻结已解除的依据，
282		// 在截止日当天给出可以办理甚至完成销毁。
283		if r, err := s.Check(CheckRequest{
284			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
285		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
286			t.Fatalf("损坏后对 A-1 的核对也必须失败，不能误报可以办理: %+v err=%v", r, err)
287		}
288		if m, err := s.Destroy(DestructionRequest{
289			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
290		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
291			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
292		}
293		if m, err := s.Destroy(DestructionRequest{
294			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
295		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
296			t.Fatalf("损坏后不得凭重复保存的解除标记销毁 A-1: %+v err=%v", m, err)
297		}
298		// 已成功申请的幂等重放同样不能取回原清册。
299		if m, err := s.Destroy(DestructionRequest{
300			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
301		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
302			t.Fatalf("损坏后已成功申请的重放也必须失败且不得返回原清册: %+v err=%v", m, err)
303		}
304		if err := s.Register(RegisterInput{
305			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
306		}); !errors.Is(err, ErrCorruptState) {
307			t.Fatalf("损坏后 Register 必须失败: %v", err)
308		}
309		if err := s.Freeze(FreezeInput{
310			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
311		}); !errors.Is(err, ErrCorruptState) {
312			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
313		}
314		if err := s.Release(ReleaseInput{
315			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
316		}); !errors.Is(err, ErrCorruptState) {
317			t.Fatalf("损坏后 Release 必须失败: %v", err)
318		}
319		if _, err := s.Revise(ReviseInput{
320			RevisionID: "R-9", ArchiveID: "A-2",
321			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
322			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
323		}); !errors.Is(err, ErrCorruptState) {
324			t.Fatalf("损坏后 Revise 必须失败: %v", err)
325		}
326	
327		// 失败不得触发修复：不选取其中一个标记、不重新保存来消除重复，
328		// 原保存内容保持原样。
329		if got := readStateFile(t, dir); got != corruptContent {
330			t.Fatalf("失败后原保存内容被改动:\n%q", got)
331		}
332	
333		// 去掉重复的解除标记后，合法记录恢复可用：A-1 的冻结仍是损坏前那条未解除
334		// 冻结，不会被重复保存的 released:true 顶替；无关档案业务不受影响。
335		writeStateFile(t, dir, good)
336		h, found, err := s.History("A-1")
337		if err != nil || !found {
338			t.Fatalf("恢复后查询应成功: found=%v err=%v", found, err)
339		}
340		if len(h.Freezes) != 1 || h.Freezes[0].ID != "F-1" || h.Freezes[0].Released {
341			t.Fatalf("恢复后 A-1 应仍保留唯一一条未解除冻结 F-1: %+v", h.Freezes)
342		}
343		if r, err := s.Check(CheckRequest{
344			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
345		}); err != nil || r.Status != CheckBlocked {
346			t.Fatalf("恢复后未解除冻结仍应阻止销毁 A-1: %+v err=%v", r, err)
347		}
348		if _, err := s.Destroy(DestructionRequest{
349			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
350		}); err != nil {
351			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
352		}
353	}
354

